// Original didactic SVG models. Labels and descriptions do not reveal the answers.
const svg=(description,body)=>`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 680 205" role="img" aria-label="${description}"><g font-family="system-ui,sans-serif" font-size="16" fill="#284c3b">${body}</g></svg>`;
const hex=(x,y)=>`<path d="M${x-17} ${y}l8-14h18l8 14-8 14h-18Z" fill="#c7dbb9" stroke="#52764c" stroke-width="2"/>`;
const chain=(points,offset=0)=>`<polyline points="${points.map(p=>p.join(',')).join(' ')}" stroke="#718e68" stroke-width="4" fill="none"/>${points.map(([x,y],i)=>`<circle cx="${x}" cy="${y}" r="8" fill="${(i+offset)%2?'#d5ad77':'#a2c28d'}" stroke="#58734e"/>`).join('')}`;
function legacyFigure(key) {
  if(key==='sugars') return `<figure class="mini-figure">${svg('A: én sekskant. B: to sammenbundne sekskanter. C: mange sammenbundne sekskanter og prikker som viser at kjeden fortsetter.', `<text x="80" y="50">A</text>${hex(87,105)}<text x="245" y="50">B</text><path d="M222 105h48" stroke="#52764c" stroke-width="3"/>${hex(222,105)}${hex(270,105)}<text x="470" y="50">C</text><path d="M390 105h228" stroke="#52764c" stroke-width="3"/>${[390,433,476,519,562].map(x=>hex(x,105)).join('')}<text x="618" y="109">…</text>`)}<figcaption>Forenklede modeller. Én sekskant = én sukkerenhet.</figcaption></figure>`;
  if(key==='protein') return `<figure class="mini-figure">${svg('Start: en foldet, sammenhengende kjede med åtte sirkler. A: de samme åtte sirklene i én utstrakt kjede. B: de åtte sirklene fordelt på tre atskilte kjedebiter.', `<text x="42" y="37">Start</text>${chain([[42,85],[69,70],[91,88],[77,113],[48,117],[47,145],[77,160],[103,143]])}<path d="M135 105H180m-8-6 8 6-8 6" fill="none" stroke="#718e68" stroke-width="2"/><text x="210" y="37">A</text>${chain(Array.from({length:8},(_,i)=>[202+i*18,100+(i%2)*12]))}<text x="420" y="37">B</text>${chain([[421,100],[440,112],[459,100]])}${chain([[497,100],[516,112],[535,100]],3)}${chain([[573,100],[592,112]],6)}`)}<figcaption>Sirklene viser aminosyrer. Strekene viser bindingene i kjeden.</figcaption></figure>`;
  if(key==='energy') return `<figure class="mini-figure">${svg('Masse per porsjon: karbohydrat 12 gram, fett 8 gram, protein 5 gram. Stolpene viser masse, ikke energi.',`<text x="20" y="27">Masse i porsjonen</text>${[['Karbohydrat',12],['Fett',8],['Protein',5]].map(([name,n],i)=>`<text x="20" y="${66+i*49}">${name}</text><rect x="160" y="${46+i*49}" width="${n*31}" height="28" rx="3" fill="#92b780"/><text x="${172+n*31}" y="${66+i*49}">${n} g</text>`).join('')}`)}<figcaption>Stolpene viser gram. Bruk energifaktorene i oppgaven.</figcaption></figure>`;
  return '';
}

// All structural drawings below are original SVGs; formulas show neutral molecules.
const ink='#253c34', green='#426a58';
const line=(x1,y1,x2,y2,more='')=>`<line x1="${x1}" y1="${y1}" x2="${x2}" y2="${y2}" stroke="${ink}" stroke-width="2" ${more}/>`;
const txt=(x,y,t,size=18,more='')=>`<text x="${x}" y="${y}" font-size="${size}" text-anchor="middle" fill="${ink}" ${more}>${t}</text>`;
const panel=(x,y,w,h)=>`<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="6" fill="#f4f7f1" stroke="#dce5d8"/>`;
const structural=(alt,body,caption='',height=250)=>`<figure class="mini-figure structure-figure"><svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 660 ${height}" role="img" aria-label="${alt}" style="display:block;width:100%;max-height:290px;background:#fff;border-radius:4px"><g font-family="system-ui,sans-serif">${body}</g></svg>${caption?`<figcaption>${caption}</figcaption>`:''}</figure>`;
function fischer(x,letter,ketose=false,galactose=false){
 const ys=ketose?[102,137,172]:[67,102,137,172],right=ketose?[false,true,true]:[true,false,!galactose,true];
 return txt(x,20,letter,20,'font-weight="700"')+txt(x,44,ketose?'CH₂OH':'CHO')+(ketose?line(x,49,x,59)+line(x,82,x,194):line(x,49,x,194))+
 (ketose?txt(x,79,'C')+line(x+9,66,x+36,66)+line(x+9,72,x+36,72)+txt(x+52,77,'O'):'')+
 ys.map((y,i)=>line(x-35,y,x+35,y)+txt(x-57,y+6,right[i]?'H':'OH')+txt(x+57,y+6,right[i]?'OH':'H')).join('')+txt(x,215,'CH₂OH');
}
const cardLabel=(x,t)=>txt(x,25,t,19,'font-weight="700"');
function acid(x,y,kind='sat'){
 const points=kind==='cis'?[[x,y],[x+25,y-20],[x+50,y],[x+75,y-20],[x+110,y-20],[x+135,y],[x+160,y-20],[x+185,y]]:[[x,y],[x+25,y-20],[x+50,y],[x+75,y-20],[x+100,y],[x+125,y-20],[x+150,y],[x+175,y-20]];
 return `<polyline points="${points.map(p=>p.join(',')).join(' ')}" fill="none" stroke="${ink}" stroke-width="2.5"/>`+
 (kind==='sat'?'':line(points[3][0]+3,points[3][1]+6,points[4][0]-3,points[4][1]+6))+txt(points[7][0]+34,points[7][1]+6,'COOH',17);
}
const molecularFigures={
 'fischer':()=>structural('Tre strukturformler med navn: A glukose, B fruktose og C galaktose. A og C har CHO øverst; B har CH₂OH øverst og C=O ved karbon 2. OH-gruppene er plassert ulikt.',fischer(105,'A · Glukose')+fischer(330,'B · Fruktose',true)+fischer(555,'C · Galaktose',false,true),'Forenklede strukturformler. Hvert kryss i den loddrette kjeden er et karbonatom.'),
 'carb-rings':()=>structural('A består av én ring; B av to ringer knyttet gjennom O; C av seks ringer med fortsatt kjede.',cardLabel(80,'A')+hex(80,110)+cardLabel(250,'B')+hex(220,110)+txt(250,116,'O')+hex(280,110)+line(237,110,241,110)+line(259,110,263,110)+cardLabel(485,'C')+[375,418,461,504,547,590].map(x=>hex(x,110)).join('')+[392,435,478,521,564].map(x=>line(x,110,x+9,110)).join('')+txt(626,116,'…'),'Én ring står for én monosakkaridenhet; forbindelsen mellom enhetene er skjematisk.',170),
 'glycosidic':()=>structural('To seksleddete ringer forbundet gjennom et oksygenatom. Forbindelsen ved oksygen er markert X. Til høyre står vann og to atskilte enheter etter en reaksjon.',cardLabel(130,'Før')+hex(85,100)+hex(175,100)+line(102,100,119,100)+txt(130,107,'O',22)+line(141,100,158,100)+txt(130,65,'X',19)+txt(260,106,'+ H₂O →',23)+cardLabel(465,'Etter')+hex(410,100)+txt(450,107,'+')+hex(505,100)+txt(575,106,'OH / H',17),'O viser oksygenet mellom sukkerenhetene. H og OH fra vannet bindes til hver sin enhet.',170),
 'polysaccharides':()=>{
 const seg=(xs,y)=>xs.map(x=>hex(x,y)).join('')+xs.slice(0,-1).map(x=>line(x+17,y,x+26,y)).join('');
 return structural('Tre kjedemodeller med navn: A er stivelse med en forgrening, B er glykogen med flere forgreninger, og C er cellulose med rette kjeder.',cardLabel(105,'A')+seg([35,78,121,164],105)+line(78,91,78,64)+hex(78,50)+txt(105,171,'Stivelse',18)+cardLabel(328,'B')+seg([245,288,331,374],105)+[245,331,374].map(x=>line(x,91,x,64)+hex(x,50)).join('')+txt(320,171,'Glykogen',18)+cardLabel(554,'C')+seg([475,518,561,604],75)+seg([475,518,561,604],125)+txt(540,171,'Cellulose',18),'Én sekskant viser én glukoseenhet. A viser et eksempel på en forgrenet stivelseskjede.',200);},
 'amino':()=>structural('NH₂ til venstre er forbundet til CH i midten, som har R nedenfor og C(=O)OH til høyre. Gruppene er merket A ved NH₂, B ved C(=O)OH og C ved R.',txt(115,115,'H₂N',26)+line(145,108,247,108)+txt(275,115,'CH',26)+line(300,108,399,108)+txt(420,115,'C',26)+line(434,108,510,108)+txt(543,115,'OH',26)+line(416,91,416,56)+line(424,91,424,56)+txt(420,44,'O',25)+line(275,125,275,173)+txt(275,202,'R',26)+txt(115,69,'A',20)+txt(517,69,'B',20)+txt(312,188,'C',20),'Nøytral strukturmodell. R står for en variabel sidegruppe.',230),
 'dipeptide':()=>structural('En kjede med H₂N–CH₂–C(=O)–NH–CH₂–C(=O)–OH. Bindingen mellom første C i C=O og NH er markert X.',txt(56,130,'H₂N',22)+line(82,123,127,123)+txt(151,130,'CH₂',22)+line(177,123,222,123)+txt(237,130,'C',22)+line(232,108,232,71)+line(242,108,242,71)+txt(237,57,'O',22)+line(252,123,310,123,'style="stroke:#b76334;stroke-width:5"')+txt(332,130,'NH',22)+line(357,123,402,123)+txt(427,130,'CH₂',22)+line(451,123,496,123)+txt(513,130,'C',22)+line(508,108,508,71)+line(518,108,518,71)+txt(513,57,'O',22)+line(528,123,575,123)+txt(599,130,'OH',22)+txt(281,100,'X',20),'Alle atomer i de viste gruppene er angitt; den fargede streken markerer én binding.',200),
 'glycerol-acid':()=>structural('A: HO–CH₂–CH(OH)–CH₂–OH vist vertikalt. B: CH₃–(CH₂)₁₆–C(=O)–OH vist horisontalt.',cardLabel(130,'A')+txt(130,74,'CH₂–OH',24)+line(107,81,107,107)+txt(130,132,'CH–OH',24)+line(107,139,107,165)+txt(130,190,'CH₂–OH',24)+cardLabel(445,'B')+txt(392,126,'CH₃–(CH₂)₁₆–C',24)+line(478,106,478,70)+line(486,106,486,70)+txt(482,59,'O',24)+line(495,119,548,119)+txt(575,126,'OH',24),'Strukturformler. Parentesen i B viser en gjentatt del av karbonkjeden.',220),
 'triglyceride':()=>structural('En vertikal kjede CH₂, CH, CH₂ der hvert karbon er forbundet til O–C(=O)–R. De tre forbindelsene O–C er markert X. R₁, R₂ og R₃ er lange hydrokarbonkjeder.',[58,123,188].map((y,i)=>txt(95,y+7,i===1?'CH':'CH₂',24)+line(122,y,200,y)+txt(222,y+7,'O',24)+line(241,y,328,y,'style="stroke:#b76334;stroke-width:4"')+txt(350,y+7,'C',24)+line(344,y-13,344,y-23)+line(354,y-13,354,y-23)+txt(350,y-30,'O',22)+line(368,y,446,y)+txt(493,y+7,['R₁','R₂','R₃'][i],24)+(i===1?txt(284,y-12,'X',18):'')).join('')+line(95,75,95,103)+line(95,140,95,168),'R₁–R₃ står for hydrokarbonkjeder. Samme type markert forbindelse finnes på alle tre radene.',240),
 'fat-chains':()=>structural('To fettsyremodeller merket A og B. A har bare enkeltbindinger; B har én markert dobbeltbinding i karbonkjeden.',cardLabel(145,'A')+acid(30,92)+cardLabel(445,'B')+acid(335,92,'cis')+txt(145,160,'A: ingen C=C',17)+txt(445,160,'B: én C=C',17)+txt(330,205,'Endepunkter og knekkpunkter uten bokstav er karbonatomer.',16),'Hydrogen på karbon er utelatt, som i vanlige skjelettformler.',230),
 'cis-trans':()=>{
 const molecule=(x,trans)=>txt(x+50,113,'C',24)+txt(x+165,113,'C',24)+line(x+67,101,x+146,101)+line(x+67,110,x+146,110)+line(x+36,91,x+11,56)+line(x+36,122,x+11,157)+line(x+180,91,x+208,56)+line(x+180,122,x+208,157)+txt(x,43,'R',22)+txt(x,182,'H',22)+txt(x+220,43,trans?'H':'R',22)+txt(x+220,182,trans?'R':'H',22);
 return structural('To C=C-grupper. I A står de to R-gruppene på samme side og H på motsatt side; i B står R-gruppene på hver sin side.',cardLabel(165,'A')+molecule(55,false)+cardLabel(495,'B')+molecule(385,true),'R står for resten av karbonkjeden. Hver C i dobbeltbindingen har én R-gruppe og ett H.',225);},
 'omega':()=>{const pts=Array.from({length:9},(_,i)=>[55+i*56,115-(i%2)*29]);return structural('En fettsyrekjede fra CH₃ til venstre, nummerert 1 til 9 fra denne enden. Dobbeltbindingen går mellom karbon 3 og 4. Syregruppen (COOH) er på høyre side.',`<polyline points="${pts.map(p=>p.join(',')).join(' ')}" fill="none" stroke="${ink}" stroke-width="2.5"/>`+line(170,121,226,92)+txt(41,139,'CH₃',18)+txt(601,120,'COOH',20)+line(503,115,557,115)+pts.map(([x,y],i)=>txt(x,y-18,String(i+1),16)).join(''),'Tell fra CH₃-enden, motsatt syregruppen (COOH). Kjeden er forkortet i modellen.',180);},
 'hydrolysis-count':()=>structural('En kjede av fem sirkler A til E med fire forbindelser mellom dem, og en pil til fem atskilte sirkler. Ingen vannmolekyler er tegnet inn.',txt(330,29,'Før',18)+[150,240,330,420,510].map((x,i)=>`<circle cx="${x}" cy="75" r="20" fill="#e1ecda" stroke="${green}"/>`+txt(x,82,'ABCDE'[i],18)+(i<4?line(x+20,75,x+70,75):'')).join('')+txt(330,129,'↓',30)+[110,220,330,440,550].map((x,i)=>`<circle cx="${x}" cy="177" r="20" fill="#e1ecda" stroke="${green}"/>`+txt(x,184,'ABCDE'[i],18)).join(''),'Hver sirkel er én byggestein; hver strek er én binding som kan spaltes med vann.',220)
};
molecularFigures['nutrient-map']=()=>{
 const box=(x,y,w,label)=>`<rect x="${x}" y="${y}" width="${w}" height="30" rx="4" fill="#f4f7f1" stroke="#8ca391"/>`+txt(x+w/2,y+21,label,15);
 const join=(x,y,x2,y2)=>line(x,y,x2,y2);
 return structural('Begrepskart. Gir energi deler seg i A, B og C. A deles videre i monosakkarider, disakkarider og polysakkarider. C deles i mettet og umettet. D deler seg i vitaminer, E og vann.',
 box(10,95,88,'Gir energi')+box(125,14,60,'A')+box(125,95,60,'B')+box(125,176,60,'C')+
 box(217,0,130,'Monosakkarider')+box(217,39,130,'Disakkarider')+box(217,78,130,'Polysakkarider')+box(217,157,130,'Mettet')+box(217,196,130,'Umettet')+
 box(395,95,60,'D')+box(504,39,145,'Vitaminer')+box(504,95,145,'E')+box(504,151,145,'Vann')+
 join(98,110,125,29)+join(98,110,125,110)+join(98,110,125,191)+
 [15,54,93].map(y=>join(185,29,217,y)).join('')+[172,211].map(y=>join(185,191,217,y)).join('')+
 [54,110,166].map(y=>join(455,110,504,y)).join(''),'Bokstavene er tomme felt som skal fylles med riktig begrep.',240);
};
molecularFigures['ndla-pepsin']=()=>structural('Søylediagram. Prøve A har pH 2 og enzymaktivitet 8 relative enheter. Prøve B har pH 7 og aktivitet 1 relativ enhet. Samme temperatur og enzymmengde.',
 line(90,185,610,185)+line(90,185,90,32)+txt(90,22,'Aktivitet',16)+[0,2,4,6,8].map(n=>line(85,185-n*17,90,185-n*17)+txt(65,191-n*17,String(n),15)).join('')+`<rect x="180" y="49" width="100" height="136" fill="#7da795"/><rect x="420" y="168" width="100" height="17" fill="#7da795"/>`+txt(230,42,'8',17)+txt(470,161,'1',17)+txt(230,211,'A: pH 2',17)+txt(470,211,'B: pH 7',17),'Relative enheter. Samme temperatur, enzymmengde og stoff som skal spaltes; bare pH varierer.',240);
export function figure(key){return molecularFigures[key]?molecularFigures[key]():legacyFigure(key);}
